    ('4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, 'Quiz — To do ou doing : le verbe choisit', 'Anglais', 'Tle', 'Infinitif et gérondif', '1c1b1a18-b68c-52aa-b005-516748c2d544'::uuid),
