    ('6768d42d-4421-58fe-b928-f2cb368d3e38'::uuid, 'Quiz — Le passé coupé du présent', 'Anglais', 'Tle', 'Le prétérit simple et le prétérit BE + -ING', '76af3eae-de32-5822-8163-1699b93cee2c'::uuid),
    ('5f558bfd-4baf-52b3-ae83-aee65e161079'::uuid, 'Quiz — Le passé qui compte encore aujourd’hui', 'Anglais', 'Tle', 'Le present perfect et le present perfect BE + -ING', 'ee03a4f0-f1d3-5da6-8080-1d5e0dae164e'::uuid),
