    ('af954e2e-bbd0-560a-9589-20e5184efa73'::uuid, 'Quiz — L’auxiliaire d’abord', 'Anglais', 'Tle', 'Les questions', 'cb65d152-b753-5b93-8da9-1158aeea7ca7'::uuid),
