    ('84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, 'Quiz — For, since, ago, during — chacun son rôle', 'Anglais', 'Tle', 'Exprimer la temporalité et la durée', 'ca23da12-b242-5b9e-a5e5-30f6a1928c81'::uuid),
    ('5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, 'Quiz — Because, since, so that, in order to', 'Anglais', 'Tle', 'Exprimer la cause et le but', '0b2d0805-0f4b-5880-b2b3-0a5a1578b08a'::uuid),
    ('b41efd7e-3e1d-5042-9558-5c86f717fdd3'::uuid, 'Quiz — If, unless, although, whereas', 'Anglais', 'Tle', 'Exprimer la condition, la concession et l’opposition', '79aaf9a0-4b14-5e44-8c9c-f301f7647aed'::uuid),
    ('66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, 'Quiz — Used to, would, be used to', 'Anglais', 'Tle', 'Exprimer l’habitude', '60bcab29-d614-5e35-bf33-f581e5a0b24d'::uuid),
    ('47aca3bc-887b-56d7-b814-0146e3817417'::uuid, 'Quiz — Make, have, get, let — la causation', 'Anglais', 'Tle', 'Faire faire quelque chose à quelqu’un', '88ca2641-267c-53f5-b1f6-8acf85c7804d'::uuid),
    ('697519a9-f302-514b-ab5f-687be3db981c'::uuid, 'Quiz — Be + participe passé', 'Anglais', 'Tle', 'La voix passive', 'fa6a87b6-c8f6-5e9d-b377-95b7bde4f0db'::uuid),
    ('b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, 'Quiz — Rapporter des paroles', 'Anglais', 'Tle', 'Le discours indirect', '7a2c2bf1-8d9c-554e-b243-e2531e4af4c8'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('56bb55cf-d2e6-5901-9f6b-65010f3fc82b'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, 'Pourquoi écrit-on « an hour » et non « a hour » ?', 'mcq', '["Parce que le h ne se prononce pas","Parce que « hour » est un nom abstrait","Parce que le mot commence par une consonne écrite","Parce que c’est une exception sans règle"]'::jsonb, 0, 'Le choix a/an dépend du SON initial, pas de la lettre.', 1),
    ('a0ac59f2-bf90-510d-a04e-e23e171989a8'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, 'On écrit « a university » et non « an university ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot commence par le son /j/ (« you »), donc « a ».', 2),
    ('543b7b4d-6a59-5b4e-9a14-78706c4896a0'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, 'Comment traduit-on « La vie est dure » ?', 'mcq', '["Life is hard","The life is hard","A life is hard","The life is the hard"]'::jsonb, 0, 'Un nom pris au sens général ne prend pas d’article en anglais.', 3),
    ('c3d4c5b1-bcb5-55c3-9353-514a38dad02a'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, '« The » s’emploie devant les noms de pays au pluriel comme *the Netherlands*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De même *the United States*, *the Philippines*.', 4),
    ('f2ab90d6-8de9-5b16-98eb-365bdc53efb1'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, 'Le génitif de « les sacs des étudiants » s’écrit…', 'mcq', '["the students’ bags","the students’s bags","the student’s bags","the bags of students"]'::jsonb, 0, 'Un pluriel déjà en -s ne prend que l’apostrophe.', 5),
    ('185bfa62-46e5-5513-bd04-41c5e7b91eef'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, 'Dans « his sister », le possessif s’accorde avec…', 'mcq', '["Le possesseur","L’objet possédé","Le verbe","Le sujet de la phrase suivante"]'::jsonb, 0, 'C’est un frère ou une sœur DE LUI : *his*, quel que soit le genre de « sister ».', 6),
    ('7b890f42-a669-5946-a214-2be53f351d5d'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, '« These » désigne ce qui est éloigné dans l’espace ou le temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*These* est proche ; *those* est éloigné.', 7),
    ('a42894b3-2405-58ef-8042-ef933f05a747'::uuid, '7cc94eb4-30d1-5e0d-a2f1-dd5bca5afd44'::uuid, 'Devant un superlatif, on emploie…', 'mcq', '["the","a","an","aucun article"]'::jsonb, 0, '*She is the best student in the class.*', 8),
    ('40bbf8fc-497b-5075-a2c4-0b7ec51ee9fd'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, 'Quel quantifieur s’emploie avec un indénombrable ?', 'mcq', '["much","many","a few","several"]'::jsonb, 0, '*Much money*, mais *many books*.', 1),
    ('b3302d53-6639-5aa3-a5fe-69bcfec32f10'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, '« A few friends » signifie « très peu d’amis, presque aucun ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*A few* est positif (« quelques ») ; c’est *few* qui est négatif.', 2),
    ('81ef630a-35d2-5852-ba2f-83b913dc65fd'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, 'Comment traduit-on « un conseil » ?', 'mcq', '["A piece of advice","An advice","A advice","One advice"]'::jsonb, 0, '*Advice* est indénombrable : il passe par *a piece of*.', 3),
    ('02c6c389-7179-54df-b54d-d770182702a9'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, 'Dans une question, on emploie normalement…', 'mcq', '["any","some","much of","a lot"]'::jsonb, 0, '*Have you got any money?* — *some* reste possible pour une offre.', 4),
    ('bb209570-3a92-58ec-9aed-449063a79831'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, '« The news is good » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*News* est un indénombrable singulier malgré son -s.', 5),
    ('8859914d-d615-5600-acd7-1c21e236cf27'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, 'Où se place « enough » avec un adjectif ?', 'mcq', '["Après l’adjectif : old enough","Avant l’adjectif : enough old","En fin de phrase uniquement","Avant le verbe"]'::jsonb, 0, 'Mais devant un nom il précède : *enough time*.', 6),
    ('5e74f6df-a39c-5ae4-8cb0-061a6159d2ee'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, '« Too much homework » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Homework* est indénombrable, donc *much* et pas *many*.', 7),
    ('c36d031d-8e44-5fb7-8c27-c19ddf8173bd'::uuid, 'a232558f-662b-5745-b7df-ecb8eea9e80a'::uuid, '« Any student can apply » signifie…', 'mcq', '["N’importe quel étudiant peut postuler","Aucun étudiant ne peut postuler","Quelques étudiants postulent","Tous les étudiants ont postulé"]'::jsonb, 0, 'À l’affirmative, *any* prend le sens de « n’importe lequel ».', 8),
    ('43606151-7b0a-50e7-b31a-6aba3324ef56'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, 'Comment traduit-on « de grands bâtiments » ?', 'mcq', '["Tall buildings","Talls buildings","Buildings tall","Tall buildingses"]'::jsonb, 0, 'L’adjectif est invariable et se place avant le nom.', 1),
    ('2fd27152-8754-5659-9159-2ccc94746b24'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, '« I am boring » signifie…', 'mcq', '["Je suis ennuyeux","Je m’ennuie","Je suis fatigué","Je suis pressé"]'::jsonb, 0, 'Pour « je m’ennuie », il faut *I am bored*.', 2),
    ('43c51a1b-bb63-5072-9d39-62a1ef61f4ec'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, 'L’adjectif en -ing décrit ce qui provoque l’émotion.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Interesting* provoque, *interested* ressent.', 3),
    ('64dda4cc-dbfc-55b2-aaf6-ecac5b524f4d'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, 'Quel est l’ordre correct ?', 'mcq', '["A big red Italian car","A red big Italian car","An Italian red big car","A red Italian big car"]'::jsonb, 0, 'Taille, puis couleur, puis origine.', 4),
    ('4057b7d9-906d-5825-99e6-00553bf044e4'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, 'Après « seem », l’adjectif reste attribut du sujet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*She seems happy* — comme après *be*, *look*, *feel*.', 5),
    ('8f16f066-8b8d-5d29-856d-ec43326f1303'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, '« The unemployed » désigne…', 'mcq', '["Les chômeurs, comme groupe","Un chômeur","Le chômage","Le licenciement"]'::jsonb, 0, '*The* + adjectif désigne l’ensemble d’un groupe.', 6),
    ('76276ffe-3aba-5114-90c8-28dd0242369a'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, '« The rich is getting richer » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’adjectif substantivé est pluriel : *the rich ARE getting richer*.', 7),
    ('49b2ad18-2c12-5d5b-a5bc-e40ae8fd4992'::uuid, 'eccf5b33-d637-5cc4-998d-80d671228a02'::uuid, 'Un adjectif anglais s’accorde en nombre avec le nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est toujours invariable, quelle que soit sa place.', 8),
    ('f81d40a0-fbcb-5f33-93bc-ed5b8400f3df'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, 'Dans « The house was built in 1920 », « was » est…', 'mcq', '["Un auxiliaire du passif","Un verbe lexical signifiant « être »","Un modal","Un auxiliaire du present perfect"]'::jsonb, 0, '*Be* + participe passé = voix passive.', 1),
    ('b5eb6139-c650-55b6-9c58-d275c1837f0e'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, 'Comment traduit-on « J’ai froid » ?', 'mcq', '["I am cold","I have cold","I have got cold","It makes me cold"]'::jsonb, 0, 'L’anglais emploie *be* là où le français emploie « avoir ».', 2),
    ('277282a4-ea02-5079-828f-7fcf934adca2'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, '« Like you tea? » est une question correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans auxiliaire, il faut en fabriquer un : *Do you like tea?*', 3),
    ('0432f6fd-6ecd-50e0-9d45-5271a0162d28'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, 'Dans « I DO like it », l’auxiliaire sert à…', 'mcq', '["Insister","Poser une question","Nier","Former un passé"]'::jsonb, 0, 'C’est l’emphase, souvent pour contredire.', 4),
    ('c09aa564-b20d-5288-b0d2-6a7ee4589e18'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, 'Dans « I have a car », « have » est un verbe lexical.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il signifie « posséder » et n’aide aucun autre verbe.', 5),
    ('2aee86b7-9a6e-56a5-a0b4-b2939c6e2d5b'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, 'Quel élément porte la négation dans une phrase anglaise ?', 'mcq', '["L’auxiliaire","Le verbe lexical","Le sujet","Le complément"]'::jsonb, 0, '*I do not know*, *she has not finished*.', 6),
    ('00b2708e-7702-5970-b5a9-0e872a804b7d'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, '« Have breakfast » signifie « posséder un petit-déjeuner ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ici *have* signifie « prendre ».', 7),
    ('cf1be89f-8db1-528e-bc21-b520d24867c5'::uuid, '4ddea00f-c8aa-5a22-9434-b21dd4539073'::uuid, 'Dans un question tag, on reprend…', 'mcq', '["L’auxiliaire de la phrase","Le verbe lexical","Le sujet seul","Un mot interrogatif"]'::jsonb, 0, '*You like it, don’t you?* — l’auxiliaire est fabriqué si besoin.', 8),
    ('adbfb026-5f2d-552a-8c71-cb4658847434'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, 'Quelle forme suit un modal ?', 'mcq', '["La base verbale sans TO","L’infinitif avec TO","Le participe présent","Le prétérit"]'::jsonb, 0, '*He can swim*, jamais *he can to swim*.', 1),
    ('43fdbdeb-2d48-5891-b35e-a12b456dbd79'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, '« He cans swim » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un modal ne prend jamais de -s à la 3e personne.', 2),
    ('cd58f6cf-578f-54bf-8199-0e8b985c4a76'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, '« You mustn’t go » signifie…', 'mcq', '["Tu ne dois pas y aller : c’est interdit","Tu n’es pas obligé d’y aller","Tu devrais y aller","Tu pourras y aller"]'::jsonb, 0, 'L’absence d’obligation, c’est *you don’t have to go*.', 3),
    ('eba40e75-4617-5f28-a481-12645725f08b'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, '« He must be tired » exprime ici…', 'mcq', '["Une déduction","Une obligation","Une permission","Une capacité passée"]'::jsonb, 0, 'C’est la valeur épistémique de *must*.', 4),
    ('28e05ca0-4a05-5b9e-b07a-b15efc159d88'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, '« He will can come » est une forme correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Deux modaux ne se suivent pas : *he will be able to come*.', 5),
    ('bb30f969-6965-5e5c-aba9-1c6e351e075a'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, '« She should have called » exprime…', 'mcq', '["Un reproche sur le passé","Une obligation future","Une capacité","Une permission"]'::jsonb, 0, 'Modal + *have* + participe passé porte un regard sur le passé.', 6),
    ('80a6d285-d670-5b75-9b06-cb710f50431e'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, 'Quelle différence entre « must » et « have to » ?', 'mcq', '["Must vient du locuteur, have to des circonstances","Must est toujours passé","Have to est un modal","Aucune différence"]'::jsonb, 0, 'D’où *I must stop smoking* (ma décision) vs *I have to work late* (on m’y oblige).', 7),
    ('b8c93148-0cb1-5fe1-b94c-a94ba5ae7ab6'::uuid, '13f5d487-83dc-5534-aff4-f8e771ea927a'::uuid, '« It might rain » exprime une possibilité incertaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*May* et *might* marquent l’éventualité.', 8),
    ('d5fc3d8f-690d-5538-a4ad-47e51728f943'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, 'Que signifie « give up » ?', 'mcq', '["Abandonner","Donner","Se lever","Rendre visite"]'::jsonb, 0, 'La particule change complètement le sens du verbe.', 1),
    ('0f67837d-4064-55fa-94e6-2b99597a2de1'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, '« Turn on it » est correct pour « allume-la ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un pronom s’intercale obligatoirement : *turn it on*.', 2),
    ('a3c2203e-925b-5fc9-9c74-924cf913d680'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, 'Que signifie « look after » ?', 'mcq', '["S’occuper de","Chercher","Regarder","Ressembler à"]'::jsonb, 0, '*Look for* = chercher, *look at* = regarder.', 3),
    ('32ba8178-6ca0-500e-8c50-83a0c550a14e'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, 'Dans un verbe prépositionnel, le complément peut s’intercaler.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La préposition est inséparable : *listen to the radio*.', 4),
    ('bcb4591c-7e52-50da-876e-e55127712d98'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, '« I look forward to hearing from you » se termine par un gérondif parce que…', 'mcq', '["« to » y est une préposition, pas la marque de l’infinitif","C’est une exception","Le verbe est irrégulier","La phrase est au passif"]'::jsonb, 0, 'Après une préposition, l’anglais met toujours la forme en -ING.', 5),
    ('ed11a124-090d-532f-96b1-78858bfe998c'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, '« Who are you waiting for? » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La préposition peut rester en fin de phrase, contrairement au français.', 6),
    ('beea9c0a-b0c3-50c0-93ef-ef1a484c7684'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, 'Que signifie « put off » ?', 'mcq', '["Reporter","Poser","Éteindre le feu","Se déshabiller"]'::jsonb, 0, '*The meeting was put off until Monday.*', 7),
    ('8a30d66d-9ea3-514b-a9df-820c9785705f'::uuid, '59c5b59f-ba26-56c7-bcbd-41ff95cb2c2a'::uuid, '« Look up a word » signifie…', 'mcq', '["Chercher un mot dans un dictionnaire","Lever les yeux vers un mot","Épeler un mot","Souligner un mot"]'::jsonb, 0, 'Encore une particule qui refait le sens du verbe.', 8),
    ('81a093d2-fde9-5183-8cc1-6d9dee45aac8'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, 'Quelle forme suit une préposition ?', 'mcq', '["La forme en -ING","L’infinitif avec TO","La base verbale","Le participe passé"]'::jsonb, 0, '*Before leaving*, *good at singing*.', 1),
    ('8ab078cd-3279-54d9-b496-872cca176a35'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, '« I look forward to see you » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ici *to* est une préposition : *to seeing you*.', 2),
    ('a8d72d66-f633-506c-af7d-e325b8c12260'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, 'Quel verbe est suivi de -ING ?', 'mcq', '["enjoy","decide","want","promise"]'::jsonb, 0, '*I enjoy reading* ; les trois autres appellent l’infinitif.', 3),
    ('e283a2f5-ec46-5cf9-98b1-9f17c2069552'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, '« I stopped smoking » signifie…', 'mcq', '["J’ai arrêté de fumer","Je me suis arrêté pour fumer","J’ai commencé à fumer","Je fume encore"]'::jsonb, 0, '*I stopped to smoke* signifierait l’inverse.', 4),
    ('35787c47-4fe7-56a8-b063-189ca894344f'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, '« Remember doing something » renvoie au souvenir d’une action déjà faite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Remember to do* signifie au contraire « penser à faire ».', 5),
    ('cfc4c8b0-1ca2-5eec-afc3-3ed8c9f62714'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, 'Après « avoid », on emploie…', 'mcq', '["-ING","to + base verbale","la base verbale seule","un participe passé"]'::jsonb, 0, '*He avoided answering the question.*', 6),
    ('095c06df-7ab4-506b-a45e-8679fc8327cc'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, '« She decided leaving » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Decide* appelle l’infinitif : *decided to leave*.', 7),
    ('585bab13-8aa4-5a28-8c8b-d2cce2af7440'::uuid, '4fdcf841-04cb-5d8c-b541-0f1b3ac2d38a'::uuid, '« Try doing » signifie…', 'mcq', '["Essayer pour voir ce que ça donne","S’efforcer difficilement","Refuser de faire","Réussir à faire"]'::jsonb, 0, '*Try to do*, lui, marque l’effort.', 8),
    ('e271eea4-2225-5865-b48e-5c3bf0f03c8a'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, 'Que signifie « hardly » ?', 'mcq', '["À peine","Durement","Difficilement","Fortement"]'::jsonb, 0, 'Faux ami classique : *I could hardly hear him.*', 1),
    ('c8ee9d58-0ee1-58d8-9f34-f2ad10d71a89'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, 'Où se place « often » dans « She works late » ?', 'mcq', '["Avant le verbe : She often works late","En fin de phrase obligatoirement","Entre le verbe et son complément","Avant le sujet"]'::jsonb, 0, 'Les adverbes de fréquence précèdent le verbe lexical.', 2),
    ('a1656f65-1718-5d5d-810a-db27688e8074'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, '« She is often late » : l’adverbe se place après « be ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *be* et les auxiliaires, l’adverbe passe derrière.', 3),
    ('23545de3-7d2f-5fbf-ac92-aef6de56848d'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, '« He speaks fluently English » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne sépare jamais le verbe de son COD : *He speaks English fluently.*', 4),
    ('580390f5-4a46-5b07-882f-7c0051304608'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, 'Quel est l’adverbe formé sur « happy » ?', 'mcq', '["happily","happyly","happly","happier"]'::jsonb, 0, 'Le -y final devient -i devant -ly.', 5),
    ('8b426747-3fa1-50b0-bed9-911b43454f2c'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, 'Comment dit-on « bien meilleur » ?', 'mcq', '["Much better","Very better","Very best","More better"]'::jsonb, 0, '*Very* ne se combine pas avec un comparatif.', 6),
    ('90da9ca9-064d-59a5-b610-cec91502fab6'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, '« Fast » a la même forme comme adjectif et comme adverbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *hard*, *late*, *early*.', 7),
    ('e63e5594-2eeb-5ad2-973d-b2fcabce1ff5'::uuid, 'd19a7f1a-cd28-58e2-b211-ffca3c60cbc0'::uuid, '« Lately » signifie…', 'mcq', '["Récemment","Tardivement","Lentement","Plus tard"]'::jsonb, 0, 'Pour « en retard », c’est *late*.', 8),
    ('c4f44318-7d67-5ebb-b8aa-4996e900c8de'::uuid, 'a669a217-c0cd-5c78-b8d0-04f4c0a6d970'::uuid, 'Quel temps pour « L’eau bout à 100 °C » ?', 'mcq', '["Le présent simple","Le présent en BE + -ING","Le prétérit","Le present perfect"]'::jsonb, 0, 'Une vérité générale appelle le présent simple.', 1),
    ('ff42fa47-6046-5066-882c-75de0a47a1fc'::uuid, 'a669a217-c0cd-5c78-b8d0-04f4c0a6d970'::uuid, '« I am knowing the answer » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Know* est un verbe d’état : *I know the answer.*', 2),
