    ('63086ed5-9aea-5335-b292-e4da04f30a65'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, 'Une relative appositive peut être introduite par « that ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Entre virgules, on emploie *who* ou *which*, jamais *that*.', 2),
    ('9158b1f5-41f8-5995-948c-fd3394fb2d8e'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, '« The book I read yesterday » est correct sans relatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le relatif complément peut s’effacer.', 3),
    ('d2192eba-1195-54d9-92b3-e790e5cc2dac'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, 'Dans « The man who called is my uncle », la relative…', 'mcq', '["Identifie de quel homme on parle","Ajoute une information accessoire","Exprime une cause","Exprime une condition"]'::jsonb, 0, 'Relative déterminative : pas de virgule.', 4),
    ('87e20384-9ecd-5812-9373-ce5c6d7d8ca9'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, 'Quel verbe exige un complément de personne ?', 'mcq', '["tell","say","think","hope"]'::jsonb, 0, '*Tell me*, mais *say to me*.', 5),
    ('4756f771-dee2-57ca-acb2-880e404c70a0'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, '« Although » introduit…', 'mcq', '["Une concession","Une cause","Un but","Une condition"]'::jsonb, 0, '*Although it was raining, we went out.*', 6),
    ('42e1a547-21bc-560e-b432-f6d00a25a307'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, 'Après « until », on emploie le futur avec « will ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme après *when* et *if* : présent obligatoire.', 7),
    ('92de8559-c71f-5949-bec7-3bca3101d732'::uuid, '9198a09f-49d3-5c85-95ac-3a3651064768'::uuid, '« So that » introduit…', 'mcq', '["Un but","Une conséquence datée","Une comparaison","Une opposition"]'::jsonb, 0, '*He left early so that he could catch the train.*', 8),
    ('e8206ec3-5cbf-555d-984a-38b1bf1a0fbd'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, 'Lequel introduit un point de départ ?', 'mcq', '["since","for","ago","during"]'::jsonb, 0, '*Since 2019*, *since Monday*.', 1),
    ('37a6047b-747d-5617-b758-c9825ef42b48'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, '« I have lived here since six years » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une durée appelle *for* : *for six years*.', 2),
    ('ade50d3e-792e-5ab4-a7f4-dd5333e4ea68'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, '« Ago » s’emploie avec…', 'mcq', '["Le prétérit","Le present perfect","Le présent","Le past perfect"]'::jsonb, 0, '*I met her three days ago.*', 3),
    ('34d25318-079e-51f6-af54-0f03edc1c4ba'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, 'Quelle forme est correcte ?', 'mcq', '["During the meeting","During we were talking","While the meeting","While of the meeting"]'::jsonb, 0, '*During* + nom, *while* + proposition.', 4),
    ('a285317b-0090-5943-99b5-57b65135da8e'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, '« By Friday » signifie « jusqu’à vendredi ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela signifie « d’ici vendredi, au plus tard » ; « jusqu’à » se dit *until*.', 5),
    ('99a54cf7-61de-57f7-add9-7dd762271dde'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, '« In two weeks » signifie…', 'mcq', '["Dans deux semaines","Il y a deux semaines","Pendant deux semaines","Depuis deux semaines"]'::jsonb, 0, 'Pour « pendant », il faudrait *for*.', 6),
    ('e964b183-ac71-562c-ab30-d87027867afb'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, '« Since » va le plus souvent avec le present perfect.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il relie un point du passé au présent.', 7),
    ('096c114e-5cb4-5c92-a0bd-f4ace6f62b7c'::uuid, '84568ab2-dde1-5998-baca-0f8a1ebddcdf'::uuid, 'Comment traduit-on « pendant la réunion » ?', 'mcq', '["During the meeting","While the meeting","For the meeting","Since the meeting"]'::jsonb, 0, 'Un nom appelle *during*.', 8),
    ('fe540eb2-5a4d-56c5-bbbb-672d54128a90'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, 'Quelle forme est correcte ?', 'mcq', '["Because of the rain","Because of it was raining","Because the rain","Due to it rained"]'::jsonb, 0, '*Because of* est suivi d’un groupe nominal.', 1),
    ('695bd264-081f-518e-a509-bc634e8643cd'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, '« I came for help you » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le but devant un verbe se dit *to help*, jamais *for to*.', 2),
    ('10c70b8a-6002-5312-bfdd-c79a8c4bc873'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, '« So that » s’emploie surtout quand…', 'mcq', '["Le sujet du but est différent","Le sujet est le même","La cause est connue","On exprime une conséquence datée"]'::jsonb, 0, '*He spoke slowly so that everyone could understand.*', 3),
    ('150970e0-3eee-52cd-99be-62169335930f'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, '« As it was late, we left » exprime une cause.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*As* et *since* introduisent une cause souvent déjà connue.', 4),
    ('6bf7591d-009d-5472-8cea-0dbabd28718a'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, 'Comment dit-on « afin de ne pas être en retard » ?', 'mcq', '["So as not to be late","So as to not be late","For not being late","To not be late"]'::jsonb, 0, 'La négation se place devant *to* dans cette structure.', 5),
    ('3a4dc970-340a-5977-8dba-006c36578e68'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, '« Thanks to » introduit une cause négative.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’emploie pour une cause positive ; sinon *because of*, *owing to*.', 6),
