    ('f9b08362-1b75-50c4-9ab8-45a17e322ff3'::uuid, '5972a6d7-8f22-5ad7-87de-02a8ea40fdfb'::uuid, '« In order to » est plus formel que « to » seul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Même sens, registre plus soutenu.', 8),
    ('d4cd1d5c-697e-57c7-aed5-d626501b41f3'::uuid, 'b41efd7e-3e1d-5042-9558-5c86f717fdd3'::uuid, '« Unless you hurry » signifie…', 'mcq', '["Si tu ne te dépêches pas","Si tu te dépêches","Bien que tu te dépêches","Pendant que tu te dépêches"]'::jsonb, 0, '*Unless* contient déjà la négation.', 1),
