    ('d53cee48-4ca0-526c-a125-6b9184dd02a1'::uuid, 'b41efd7e-3e1d-5042-9558-5c86f717fdd3'::uuid, 'Quelle structure suit « in spite of » ?', 'mcq', '["Un nom ou un -ING","Une proposition complète","Un infinitif","Un modal"]'::jsonb, 0, 'Comme *despite*.', 3),
