    ('06637d7e-b864-5b4c-8035-d93489de358e'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, '« I used to smoke » signifie…', 'mcq', '["Je fumais autrefois, mais plus maintenant","J’ai l’habitude de fumer","Je me suis habitué à fumer","Je vais fumer"]'::jsonb, 0, '*Used to* implique toujours une rupture avec le présent.', 1),
    ('d048b794-88e8-5b98-b0fa-170d19997422'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, '« I’m used to getting up early » signifie…', 'mcq', '["J’ai l’habitude de me lever tôt","Je me levais tôt autrefois","Je vais me lever tôt","Je déteste me lever tôt"]'::jsonb, 0, 'Ici *to* est une préposition, d’où le -ING.', 2),
    ('dbe2c747-92c2-522f-8618-1bb7eb7a20e4'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, '« I would live in York » est correct pour une habitude passée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Would* ne s’emploie pas pour un état : *I used to live in York*.', 3),
    ('45f4cfbf-f656-5af8-a1d0-a4db7674595f'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, 'La négation de « used to » est…', 'mcq', '["I didn’t use to","I didn’t used to","I usen’t to","I not used to"]'::jsonb, 0, '*Did* porte le passé, donc *use* sans -d.', 4),
