    ('5a1bf837-5466-56b6-a44b-8afcfa038678'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, '« Get used to » signifie…', 'mcq', '["S’habituer progressivement","Avoir toujours été habitué","Perdre une habitude","Refuser une habitude"]'::jsonb, 0, '*You’ll get used to it.*', 6),
    ('dba36bdd-0896-5644-abc9-64391fe07de0'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, 'L’habitude au présent se rend par…', 'mcq', '["Le présent simple + adverbe de fréquence","used to + base verbale","would + base verbale","be + -ing"]'::jsonb, 0, '*I usually walk to school.*', 7),
    ('9e32ddbd-4fc5-5869-a7f7-091b4e841b22'::uuid, '66677fb4-912e-5a89-b818-b2ae3408682e'::uuid, 'Après « be used to », on emploie la base verbale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie la forme en -ING : *used to getting up*.', 8),
    ('514d89aa-dfb0-5d2a-9469-80a6d40b800a'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, 'Quelle construction suit « make » à l’actif ?', 'mcq', '["make + complément + base verbale","make + complément + to + base verbale","make + -ing","make + participe passé"]'::jsonb, 0, '*She made me wait.*', 1),
    ('815a51a3-1aaf-5fb2-a827-2ab59920188c'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, '« I was made to wait » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Au passif, *make* retrouve le *to*.', 2),
    ('e7918118-7a8f-53c9-92aa-eb1f4e3ff0ac'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, 'Lequel se construit avec « to » ?', 'mcq', '["get","make","have","let"]'::jsonb, 0, '*I got him to help me.*', 3),
    ('3a827f94-0274-5073-98d0-096ddcbf996c'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, '« I had my hair cut » signifie…', 'mcq', '["Je me suis fait couper les cheveux","J’ai coupé mes cheveux moi-même","J’avais les cheveux coupés courts","Je voulais couper mes cheveux"]'::jsonb, 0, 'La structure *have something done* désigne l’action d’un tiers.', 4),
    ('09ee46e5-ec96-55fe-a75a-c7ad3f9901ef'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, '« Let » exprime la permission.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Let me explain*, *they let him go*.', 5),
    ('dc0f79e5-a078-5429-8b79-ffd1fba34743'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, 'Au passif, on remplace « let » par…', 'mcq', '["allow","make","have","get"]'::jsonb, 0, '*He was allowed to go.*', 6),
    ('fd250bda-6c2f-5cc8-b8e9-5f81c4ca800f'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, '« She got her car repaired » signifie qu’elle a réparé la voiture elle-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’a fait réparer : structure *get something done*.', 7),
    ('ca6a973f-3e49-5666-8603-5527c3ab716d'::uuid, '47aca3bc-887b-56d7-b814-0146e3817417'::uuid, '« I had the mechanic check the brakes » implique…', 'mcq', '["Une demande à quelqu’un dont c’est le métier","Une contrainte violente","Une permission accordée","Une interdiction"]'::jsonb, 0, '*Have* + complément + base verbale, sans contrainte.', 8),
    ('90632310-d18c-5200-9be0-cda6d23d193a'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, 'Comment se forme le passif ?', 'mcq', '["be + participe passé","have + participe passé","be + -ing","do + base verbale"]'::jsonb, 0, '*The house was built in 1920.*', 1),
    ('fffb8e23-0105-5408-abc9-249ad76b1623'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, 'Dans un passif, qu’est-ce qui porte le temps ?', 'mcq', '["L’auxiliaire be","Le participe passé","Le complément d’agent","Le sujet"]'::jsonb, 0, '*Is made*, *was made*, *will be made*.', 2),
    ('ebdfc8be-389f-52e7-9b46-fa9acc5f68ab'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, 'Le complément d’agent est introduit par « by ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et il est le plus souvent omis.', 3),
    ('0279a436-3cc7-5eba-bbcb-2fcfa6b0f0f4'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, '« They gave John a prize » donne au passif, plus naturellement…', 'mcq', '["John was given a prize","A prize was given John","John gave was a prize","A prize gave John"]'::jsonb, 0, 'L’anglais passive volontiers la personne.', 4),
    ('399925cb-2523-5278-b5dd-627d76445e40'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, '« He is said to have left the country » signifie…', 'mcq', '["Il aurait quitté le pays","Il a dit qu’il partait","On lui a dit de partir","Il doit quitter le pays"]'::jsonb, 0, 'Tournure impersonnelle fréquente dans la presse.', 5),
    ('63375cf5-d9ce-5bc8-bec9-16e320883bce'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, 'L’anglais emploie le passif moins souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il l’emploie beaucoup plus, surtout à l’écrit informatif.', 6),
    ('e9af4e18-3f84-5061-b20f-42ff412ab5f3'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, '« My bike was stolen » n’exprime pas l’agent parce que…', 'mcq', '["Il est inconnu","Il est interdit de l’exprimer","Le verbe le refuse","La phrase est au présent"]'::jsonb, 0, 'C’est le cas le plus courant du passif.', 7),
    ('3b6a4ef1-00ab-516b-809c-5c2b8a406b40'::uuid, '697519a9-f302-514b-ab5f-687be3db981c'::uuid, '« The house is being built » est un passif en cours.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Be* + *being* + participe passé.', 8),
    ('fb51dff8-f25c-53fe-9874-11778a87be40'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, 'Au discours indirect passé, un présent devient…', 'mcq', '["Un prétérit","Un present perfect","Un past perfect","Un conditionnel"]'::jsonb, 0, '*« I am tired » → He said he was tired.*', 1),
    ('7c6ddbcf-d9e6-5486-8270-422b6f3b7db5'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, '« I have finished » devient au discours indirect…', 'mcq', '["He said he had finished","He said he has finished","He said he finished","He said he would finish"]'::jsonb, 0, 'Le present perfect recule en past perfect.', 2),
    ('47e2c05b-13b8-54e8-a911-58376768514d'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, '« He said me that… » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Say* n’admet pas de complément de personne : *he told me*.', 3),
    ('f1021689-2d82-56ea-910d-e815bed07738'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, 'Dans une question indirecte, on garde l’inversion sujet-auxiliaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*He asked where she lived*, sans *did* ni inversion.', 4),
    ('d3049aaf-316c-50f9-8e3f-f929de5dbf4d'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, 'Sans mot interrogatif, la question indirecte s’introduit par…', 'mcq', '["if ou whether","that","what","so"]'::jsonb, 0, '*He asked if I was ready.*', 5),
    ('0a901552-1e80-59e4-a963-230e85f5f727'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, '« Tomorrow » devient au discours indirect passé…', 'mcq', '["the next day","that day","the day before","now"]'::jsonb, 0, 'Les repères se déplacent avec le point de vue.', 6),
    ('937539a3-0fd6-5aff-8377-7d21b090483e'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, 'Un ordre rapporté se rend par un infinitif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He told me to sit down*, *he told me not to move*.', 7),
    ('1284bf45-6430-5791-b181-29b290e1f0ff'::uuid, 'b5aa6ca9-ec0e-5589-a547-6f455f18489f'::uuid, '« Must » devient au discours indirect passé…', 'mcq', '["had to","musted","would must","could"]'::jsonb, 0, '*Must* n’a pas de forme passée propre.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('anglais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('anglais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 226 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 226 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
